    start.setDate(start.getDate() - Math.max(1, Number(days || 90)) + 1);
    state.brandMedia.quickRange = String(days);
    state.brandMedia.startDate = _brandMediaIsoDate(start);
    state.brandMedia.endDate = _brandMediaIsoDate(end);
